  function addApiEvent(event){const now=new Date().toLocaleTimeString('en-GB');document.getElementById('apiPayload').textContent=JSON.stringify({event,orderId:'WO-204842',occurredAt:new Date().toISOString(),idempotencyKey:'evt-'+Date.now(),source:'contractor-api'},null,2);document.getElementById('eventLog').insertAdjacentHTML('afterbegin','<div><i class="status-dot"></i><b>'+now+'</b> '+event+' → HomeSafe OS <span>202</span></div>');document.getElementById('contractorStatus').textContent=eventNames[event]||'API update received';notify(eventNames[event]||event+' received')}
  document.querySelectorAll('.contractor-action').forEach(b=>b.onclick=()=>addApiEvent(b.dataset.event));
  document.getElementById('sendApi').onclick=()=>addApiEvent('visit.progress.updated');
  document.getElementById('logSnag').onclick=()=>snagModal.classList.add('open');snagModal.querySelectorAll('.snag-close').forEach(b=>b.onclick=closeSnag);snagModal.onclick=e=>{if(e.target===snagModal)closeSnag()};
  document.getElementById('createSnag').onclick=()=>{const id='SNG-'+(1043+document.querySelectorAll('#snagTable tr').length-3);const severity=document.getElementById('snagSeverity').value.startsWith('Critical')?'Critical':'Open';document.getElementById('snagTable').insertAdjacentHTML('beforeend','<tr><td><b>'+id+'</b><br>'+document.getElementById('snagDesc').value+'</td><td>'+document.getElementById('snagSpec').value.split(' • ')[0]+' • '+document.getElementById('snagLocation').value+'</td><td>'+document.getElementById('snagOwner').value+'</td><td>5 Aug</td><td><i class="pill '+(severity==='Critical'?'red':'amber')+'">'+severity+'</i></td></tr>');document.getElementById('snagCount').textContent=Number(document.getElementById('snagCount').textContent)+1;closeSnag();notify(id+' logged, rectification order issued and £318 payment retention applied')};
  const originalCreate=[...document.querySelectorAll('[data-toast]')].find(b=>b.dataset.toast&&b.dataset.toast.includes('HZ-24019'));
  if(originalCreate)originalCreate.onclick=openModal;
  function renderBoard(){const defaults=[{id:'WO-204981',desc:'Emergency leak / isolate electrics',home:'14 Orchard Walk',supplier:'FixRight Ltd',appt:'Today 12:00',status:'Dispatched',risk:'Emergency',cost:'£184.70'},{id:'WO-204977',desc:'Damp inspection & moisture readings',home:'82 Ashton New Road',supplier:'Survey team',appt:'Today 14:30',status:'Booked',risk:'Significant',cost:'£92.00'},{id:'WO-204965',desc:'Boiler no heat — vulnerable household',home:'4 Kincardine Road',supplier:'HeatServe',appt:'Today 16:00',status:'At risk',risk:'Significant',cost:'£126.40'},{id:'WO-204901',desc:'Fire door closer replacement',home:'Block C, Grey Mare Lane',supplier:'SafeDoor NW',appt:'Tomorrow',status:'Awaiting materials',risk:'Compliance',cost:'£211.65'}];const all=[...state.jobs,...defaults];const lanes=[['New / triage',x=>x.status==='Booked'],['Assigned',x=>x.status==='Dispatched'],['At risk',x=>x.status==='At risk'||x.status==='Awaiting materials'],['Complete',x=>x.status==='Complete']];const k=document.getElementById('kanban');k.innerHTML=lanes.map(([name,fn])=>{const jobs=all.filter(fn);return '<div class="lane"><h3>'+name+' <span>'+jobs.length+'</span></h3>'+jobs.map(j=>'<div class="ticket '+(j.risk==='Emergency'?'red':j.status.includes('risk')?'amber':'')+'"><b>'+j.id+'</b><small>'+j.desc+'</small><small>'+j.home+'</small><footer><span>'+j.supplier+'</span><b>'+j.cost+'</b></footer></div>').join('')+'</div>'}).join('')}
  function refreshAwaab(){const owners=['Contact centre','Housing officer','Surveyor','R&M planning','Operative / contractor','Quality inspector','Accounts'];const step=Number(localStorage.getItem('homesafeFlowStep')||0);document.getElementById('awaabOwner').textContent=owners[Math.min(step,owners.length-1)]}function goAdvanced(id,label){document.querySelectorAll('.panel').forEach(x=>x.classList.remove('on'));document.querySelectorAll('nav button').forEach(x=>x.classList.toggle('on',x.dataset.view===id));document.getElementById(id).classList.add('on');title.textContent=label;refreshAwaab();scrollTo(0,0);if(id==='livejobs')renderBoard()}
  function notify(msg){const t=document.getElementById('toast');t.textContent='✓ '+msg;t.classList.add('on');setTimeout(()=>t.classList.remove('on'),2800)}
  document.querySelectorAll('[data-adv-toast]').forEach(b=>b.onclick=()=>notify(b.dataset.advToast));
  document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();closeSnag()}});renderBoard();
  document.getElementById('openAwaab').onclick=()=>{const workflowButton=document.querySelector('nav button[data-view="workflow"]');if(workflowButton)workflowButton.click()};refreshAwaab();const globalCss=document.createElement('link');globalCss.rel='stylesheet';globalCss.href='global.css?v=10';document.head.appendChild(globalCss);const tabletCss=document.createElement('link');tabletCss.rel='stylesheet';tabletCss.href='tablet.css?v=10';document.head.appendChild(tabletCss);const workflowCss=document.createElement('link');workflowCss.rel='stylesheet';workflowCss.href='workflow.css?v=10';document.head.appendChild(workflowCss);const contactCss=document.createElement('link');contactCss.rel='stylesheet';contactCss.href='contactcentre.css?v=10';document.head.appendChild(contactCss);
